"use client";

import React, { useState } from "react";
import { Mail } from "lucide-react";

export function CRMLeadCard() {
  const [status, setStatus] = useState("Hot");

  return (
    <div className="w-full max-w-xs bg-card/45 backdrop-blur-xl border border-border/50 rounded-2xl shadow-xl select-none font-sans overflow-hidden text-foreground">
      <div className="p-4 space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-violet-500 to-indigo-500 flex items-center justify-center font-bold text-white text-xs">
              JD
            </div>
            <div>
              <h4 className="text-xs font-black leading-none mb-1">Jane Doe</h4>
              <span className="text-[9px] text-muted-foreground">Product Director, TechGroup</span>
            </div>
          </div>
          <span className={`text-[9px] uppercase font-bold px-2 py-0.5 rounded border ${
            status === "Hot" ? "bg-rose-500/10 text-rose-400 border-rose-500/20" : "bg-secondary text-muted-foreground border-border"
          }`}>{status} Lead</span>
        </div>

        <div className="pt-2 border-t border-white/[0.04] flex items-center justify-between text-xs">
          <span className="text-muted-foreground/60 flex items-center gap-1"><Mail className="w-3.5 h-3.5" /> jane@techgroup.com</span>
          <button 
            onClick={() => setStatus(status === "Hot" ? "Warm" : "Hot")}
            className="text-violet-400 font-bold hover:text-violet-300 transition-colors"
          >
            Adjust
          </button>
        </div>
      </div>
    </div>
  );
}
